INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6578227, 978969, 20799, '<td valign="top">As I said before - love the cyan! This is one place where you can use it in huge amounts :).</td>', 'As I said before - love the cyan! This is one place where you can use it in huge amounts :).', '2011-10-28 04:47:33.000000', NULL, 0),
(6578983, 979073, 20799, '<td valign="top">Interesting scene. I would have had complaints about the water and the rock in front, but that unusual color contrast distracts me from my perceived flaws very elegantly :). <br/>I''m curious about the red/orange colors at the top, probably sunset in the trees...?</td>', 'Interesting scene. I would have had complaints about the water and the rock in front, but that unusual color contrast distracts me from my perceived flaws very elegantly :). I''m curious about the red/orange colors at the top, probably sunset in the trees...?', '2011-10-29 15:35:54.000000', NULL, 0),
(6579761, 978916, 59029, '<td valign="top">Maybe a teeny tiny bit overexposed, but seems to balance the darkness in the lower regions.  And pretty good pic and finish for someone who rarely enters challenges! :-)</td>', 'Maybe a teeny tiny bit overexposed, but seems to balance the darkness in the lower regions.  And pretty good pic and finish for someone who rarely enters challenges! :-)', '2011-10-31 00:45:30.000000', NULL, 0),
(6586934, 979187, 29011, '<td valign="top">Like a landscape from another world. A fine abstract!</td>', 'Like a landscape from another world. A fine abstract!', '2011-11-06 22:41:02.000000', NULL, 0),
(6771126, 979083, 104009, '<td valign="top">how did i only give this a 6?  how jaded i must have been.  this is so beautiful</td>', 'how did i only give this a 6?  how jaded i must have been.  this is so beautiful', '2012-05-16 19:43:32.000000', NULL, 0),
(6771350, 979083, 93565, '<td valign="top">Man, I don''t recall seeing this. It''s a gorgeous photo, and the sunburst is just the cream on top.</td>', 'Man, I don''t recall seeing this. It''s a gorgeous photo, and the sunburst is just the cream on top.', '2012-05-17 05:54:12.000000', NULL, 0),
(6825019, 978601, 8759, '<td valign="top">Awesome. I favoured it. <br/> <br/>Two month later after its departure from the US I could see her in Hong Kong. <br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=991000" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/1000-1999/1505/120/Copyrighted_Image_Reuse_Prohibited_991000.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/1000-1999/1505/120/Copyrighted_Image_Reuse_Prohibited_991000.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/1000-1999/1505/120/Copyrighted_Image_Reuse_Prohibited_991000.jpg"/></a></td>', 'Awesome. I favoured it.  Two month later after its departure from the US I could see her in Hong Kong.  ', '2012-07-23 01:51:57.000000', NULL, 0),
(6869011, 978601, 86218, '<td valign="top">Stunning shot here. Combining this moody landscape with a fortress of war like this is so contrasting and yet the mist spells doom. Love it. Fav</td>', 'Stunning shot here. Combining this moody landscape with a fortress of war like this is so contrasting and yet the mist spells doom. Love it. Fav', '2012-09-25 07:24:36.000000', NULL, 0),
(6944395, 979067, 30982, '<td valign="top">A lovely, peaceful place.  I like the rich color in the reflection.</td>', 'A lovely, peaceful place.  I like the rich color in the reflection.', '2012-12-29 20:05:05.000000', NULL, 0),
(6984968, 978812, 30982, '<td valign="top">The light coming off the water is gorgeous.  I think this is really nicely balanced - nice work with the composition.</td>', 'The light coming off the water is gorgeous.  I think this is really nicely balanced - nice work with the composition.', '2013-02-24 00:41:04.000000', NULL, 0),
(7002090, 978812, 123348, '<td valign="top">Wow, that is magnificent! Definitely have to put this place on my bucket list... :) Wonderful capture Marcia! (Thank you for your lovely comments!)<br/><br/><i>Message edited by author 2013-03-18 00:08:10.</i></td>', 'Wow, that is magnificent! Definitely have to put this place on my bucket list... :) Wonderful capture Marcia! (Thank you for your lovely comments!)', '2013-03-18 00:07:30.000000', '2013-03-18 00:08:10.000000', 0),
(7043672, 978812, 108580, '<td valign="top">Beautiful scene. Great positioning to get river and valley in an appealing composition. I''d apply a bit of subtle HDR/Tone Mapping in sky and land to make it pop some more. Perhaps an inch off the top as Rian suggests but not too much! The sky is very dramatic.</td>', 'Beautiful scene. Great positioning to get river and valley in an appealing composition. I''d apply a bit of subtle HDR/Tone Mapping in sky and land to make it pop some more. Perhaps an inch off the top as Rian suggests but not too much! The sky is very dramatic.', '2013-05-27 05:21:49.000000', NULL, 0),
(7164849, 979064, 113591, '<td valign="top">Dramatic.</td>', 'Dramatic.', '2014-01-29 09:27:16.000000', NULL, 0),
(7251932, 979122, 150277, '<td valign="top">Underrated IMHO.  This is just beautiful.  I love how you captured the movement of the boat and smoothness of the water.</td>', 'Underrated IMHO.  This is just beautiful.  I love how you captured the movement of the boat and smoothness of the water.', '2014-08-16 11:50:41.000000', NULL, 0),
(7501865, 979187, 28742, '<td valign="top">I gave this a 3 back in 2011. I''m bumping to a 5.</td>', 'I gave this a 3 back in 2011. I''m bumping to a 5.', '2017-02-23 16:05:44.000000', NULL, 0),
